    async execute(args, exec) {
      guard()
      const mode = getMode()
      if (mode !== 'read' && mode !== 'ask' && mode !== 'write') throw new Error('ChatGPT connectors are turned off in the plugin settings')
      const tool = await find(args.name, exec.signal)
