      "content": "{\n  \"name\": \"dsh-codex-subscription\",\n  \"version\": \"3.2.3\",\n  \"packageManager\": \"pnpm@11.26.0\",\n  \"description\": \"Use ChatGPT and Codex subscriptions in DeepSeek Harness with OAuth, quota, safe resets, web search, images and Fast mode, and control DSH from the ChatGPT mobile app (Beta)\",\n  \"type\": \"module\",\n  \"main\": \"./lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\",\n    \"./locale/*.json\": \"./locale/*.json\"\n  },\n  \"files\": [\n    \"lib/*.js\",\n    \"native/linux-voice-helper.py\",\n    \"locale/*.json\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README.en.md\",\n    \"DIRECTORY.md\",\n    \"compatibility.json\",\n    \"LICENSE\",\n    \"SECURITY.md\",\n    \"THIRD_PARTY_NOTICES.md\",\n    \"icon-subscription.webp\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-api-remotes\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-ui-conversation\",\n        \"@deepseek-ai/dsh-client-ui-model-selection\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-tool\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"tsdown --config tsdown.config.mjs\",\n    \"test:behavior\": \"node scripts/run-tests.mjs behavior\",\n    \"test:delivery\": \"node scripts/run-tests.mjs delivery\",\n    \"test\": \"node --test tests/*.test.mjs\",\n    \"check\": \"pnpm run test && pnpm run build && pnpm pack --pack-destination .artifacts\"\n  },\n  \"keywords\": [\n    \"dsh-plugin\",\n    \"deepseek\",\n    \"deepseek-harness\",\n    \"dsh\",\n    \"openai-codex\",\n    \"chatgpt-oauth\",\n    \"chatgpt\",\n    \"ch